// נוצר אוטומטית מ-sims-src/ ע"י tools/build-sims.js. לא לערוך כאן.
const SIMS = [{"id":"s1","title":"סימולציה 1 · בסיס","level":1,"hi":115,"chapters":[{"type":"sc","qs":[{"q":"Many students drink coffee in the evening ___ they have to study late for their exams.","o":["unless","because","although","whereas"],"a":1,"ex":"«because» = כי, מפני ש. החלק השני (צריך ללמוד עד מאוחר) הוא הסיבה לחלק הראשון (שותים קפה בערב). «although» היה יוצר ניגוד, אבל אין כאן שום ניגוד.","w":[["because","כי, מפני ש..."],["although","למרות ש..."]]},{"q":"Doctors say that regular exercise can ___ your sleep, so people who walk every day often rest better at night.","o":["improve","avoid","delay","waste"],"a":0,"ex":"«improve» = לשפר. סוף המשפט אומר שמי שהולך כל יום ישן טוב יותר, ולכן הפעילות משפרת את השינה. «delay» (לדחות) או «waste» (לבזבז) היו אומרים שהשינה נפגעת.","w":[["improve","לשפר"],["regular","קבוע, סדיר"]]},{"q":"___ the museum is free on Sundays, very few people visit it during the winter.","o":["Since","Unless","As soon as","Although"],"a":3,"ex":"«Although» = למרות ש. היינו מצפים שכניסה חינם תביא הרבה מבקרים, אבל מגיעים מעט: זה ניגוד, ולכן צריך מילת ויתור. «Since» (מכיוון ש) היה אומר שהכניסה החינמית היא הסיבה לכך שמעטים מגיעים, וזה לא הגיוני.","w":[["although","למרות ש..."],["since","מכיוון ש..."]]},{"q":"The number of small shops in the town center has ___ sharply in recent years, as more people now buy everything online.","o":["appeared","repaired","declined","celebrated"],"a":2,"ex":"«decline» = לרדת, לפחות. אנשים קונים באינטרנט, ולכן מספר החנויות ירד. «sharply» (בחדות) מתאר שינוי בכמות, וזה מתאים רק ל-«declined».","w":[["decline","לרדת, לפחות"],["sharply","בחדות"]]}]},{"type":"sc","qs":[{"q":"To save money, Dana decided to cook dinner at home ___ eating at an expensive restaurant every night.","o":["because of","in addition to","instead of","as a result of"],"a":2,"ex":"«instead of» = במקום. כדי לחסוך, דנה מבשלת בבית במקום לאכול במסעדה יקרה. «in addition to» (בנוסף ל) היה אומר שהיא גם אוכלת במסעדה כל ערב, וזה לא חוסך כסף.","w":[["instead of","במקום (+שם עצם / ing)"],["in addition to","בנוסף ל... (+שם עצם)"]]},{"q":"Because infections spread easily, most hospitals ___ visitors to wash their hands; anyone who refuses is not allowed to enter.","o":["forbid","require","pay","encourage"],"a":1,"ex":"«require» = לדרוש, לחייב. מי שמסרב לא נכנס, כלומר זו חובה ולא המלצה. «encourage» (לעודד) מפתה, אבל עידוד לא בא עם עונש למי שמסרב.","w":[["require","לדרוש, לחייב"],["refuse","לסרב"]]},{"q":"You will not be able to join the trip ___ you return the signed form by Friday.","o":["unless","because","so that","although"],"a":0,"ex":"«unless» = אלא אם כן. לא תוכל להצטרף לטיול אלא אם תחזיר את הטופס: זה תנאי. «because» היה אומר שהחזרת הטופס היא הסיבה שלא תצטרף, וזה הפוך מההיגיון.","w":[["unless","אלא אם כן"],["so that","כדי ש... (+משפט)"]]},{"q":"Archaeologists found ___ coins in the desert that were used by traders more than two thousand years ago.","o":["modern","plastic","electronic","ancient"],"a":3,"ex":"«ancient» = עתיק. מטבעות שהשתמשו בהם לפני יותר מאלפיים שנה הם עתיקים. «modern» (מודרני) הוא בדיוק ההפך.","w":[["ancient","עתיק"],["trader","סוחר"]]}]},{"type":"rc","title":"Travelers in the Dark","text":["Every spring and autumn, billions of birds travel thousands of kilometers between their summer and winter homes. What surprises many people is that a large number of these birds, including most small songbirds, make their journeys at night. While we sleep, the sky above us may be full of tiny travelers that we never see.","Scientists believe there are several reasons for this behavior. First, the air at night is usually cooler and calmer than during the day. Flying is hard work, and small birds can easily lose too much water if they fly under a hot sun. Cool night air helps them avoid this danger. In addition, the dark sky protects them from hawks and other hunters, which mostly look for food in daylight.","Night travel also allows birds to use their time well. During the day, they can rest and eat in fields and forests, so they replace the energy they used the night before. Without these daily stops, few birds would have enough strength to complete such a long trip.","But how do birds find their way in the dark? Research shows that they use several tools at once. Some young birds learn the pattern of the stars, especially the stars around the North Star, which hardly moves during the night. Birds can also sense the earth's magnetic field, which works for them like a natural compass. Unfortunately, bright city lights can confuse them, and many birds crash into tall buildings. For this reason, some cities now ask building owners to turn off unnecessary lights during migration season."],"qs":[{"q":"The passage mainly discusses","o":["the dangers that hawks present to small songbirds","why many birds migrate at night and how they find their way","how cities have reduced the number of birds in the sky","the differences between the summer and winter homes of birds"],"a":1,"ex":"הקטע כולו עוסק בשתי שאלות: למה ציפורים נודדות בלילה (פסקאות 2-3) ואיך הן מוצאות את הדרך בחושך (פסקה 4). הנצים מוזכרים רק במשפט אחד, ולכן זו לא התשובה הכללית.","w":[["migrate","לנדוד"],["mainly","בעיקר"]]},{"q":"According to the second paragraph, one advantage of flying at night is that","o":["birds can find more food in the dark","the stars are easier to see in autumn","hawks are more active after sunset","birds lose less water in the cool air"],"a":3,"ex":"בפסקה 2 כתוב שבשמש חמה ציפורים קטנות מאבדות יותר מדי מים, ושאוויר הלילה הקריר עוזר להן להימנע מזה. לגבי הנצים כתוב ההפך: הם צדים בעיקר ביום.","w":[["advantage","יתרון"],["avoid","להימנע מ..."]]},{"q":"In the third paragraph, the word 'they' in 'so they replace the energy' refers to","o":["the birds","the fields and forests","the days","the hunters"],"a":0,"ex":"מי שנח ואוכל ביום וכך ממלא את האנרגיה שבזבז בלילה הן הציפורים. שדות ויערות הם רק המקום שבו הן נחות.","w":[["replace","להחליף, למלא מחדש"],["energy","אנרגיה, כוח"]]},{"q":"The main purpose of the last sentence of the passage is to","o":["explain why birds prefer to fly near big cities","show that the North Star is difficult to see from cities","describe one step that is taken to protect migrating birds","prove that birds cannot use the earth's magnetic field"],"a":2,"ex":"המשפט האחרון מתחיל ב-«For this reason» (מסיבה זו): בגלל שהאורות מבלבלים את הציפורים, ערים מבקשות לכבות אורות מיותרים. זה צעד שנועד להגן עליהן. הקטע לא אומר שציפורים מעדיפות ערים.","w":[["for this reason","מסיבה זו"],["unnecessary","מיותר"]]},{"q":"It can be inferred from paragraph 3 that if birds could not stop during the day,","o":["they would fly faster at night","most of them would not finish their journey","they would learn the stars more quickly","hunters would stop looking for them"],"a":1,"ex":"בפסקה 3 כתוב שבלי העצירות היומיות מעט ציפורים (few birds) היו מצליחות להשלים את המסע. כלומר רובן לא היו מסיימות אותו. אין בקטע שום דבר על טיסה מהירה יותר.","w":[["infer","להסיק"],["few","מעט (כמעט אין)"]]}]},{"type":"rs","qs":[{"q":"Although the new bridge cost much more than planned, most residents believe it was worth the money because it cut their travel time in half.","o":["Because the new bridge cost much more than planned, most residents believe it was not worth the money.","Most residents believe the new bridge was worth the money, since it cost less than planned and cut their travel time.","The new bridge was far more expensive than expected; nevertheless, most residents think it was a good investment, since it halved their travel time.","Only a few residents think the new bridge was worth the money, even though it cut their travel time in half."],"a":2,"ex":"«Although» הוחלף ב-«nevertheless» (למרות זאת), ו-«cut in half» הוחלף ב-«halved». המשמעות זהה: הגשר יקר, ובכל זאת רוב התושבים חושבים שהוא שווה. בתשובה האחרונה «Only a few» (רק מעטים) הופך את «most» (רוב).","w":[["nevertheless","למרות זאת, אף על פי כן"],["worth","שווה"],["resident","תושב"]]},{"q":"Unless farmers receive more rain this winter, they will have to plant fewer crops next year, which may raise food prices.","o":["If there is not more rain this winter, farmers will need to reduce the crops they plant next year, and food may become more expensive.","Even if more rain falls this winter, farmers will plant fewer crops next year, so food prices will certainly go down.","Farmers will plant more crops next year only if food prices rise during this winter.","Because farmers received a lot of rain this winter, they will plant fewer crops, and food prices may fall."],"a":0,"ex":"«Unless» = אלא אם כן, ובמילים אחרות «If ... not». התשובה הנכונה שומרת את התנאי (בלי גשם), את התוצאה (פחות גידולים) ואת האפשרות שהמחירים יעלו. «Even if» (גם אם) מבטל את התנאי, ושם המחירים גם יורדים.","w":[["unless","אלא אם כן"],["even if","גם אם, אפילו אם"],["crop","יבול, גידול חקלאי"]]},{"q":"Children who read for pleasure every day tend to develop a richer vocabulary than children who read only for school assignments.","o":["Children who read only for school assignments usually know more words than those who read for fun.","Reading every day for pleasure makes it harder for children to finish their school assignments.","All children develop the same vocabulary, whether they read for fun or only for school.","Daily reading for enjoyment generally helps children learn more words than reading that is done just for school tasks."],"a":3,"ex":"«for pleasure» = «for enjoyment», ו-«richer vocabulary» = יודעים יותר מילים. התשובה הראשונה הופכת את ההשוואה, כאילו מי שקורא רק לבית הספר יודע יותר מילים.","w":[["tend to","נוטה ל..."],["vocabulary","אוצר מילים"],["assignment","מטלה"]]}]},{"type":"rs","qs":[{"q":"Many people avoid going to the dentist because they are afraid of pain, even though modern treatments are usually quick and almost painless.","o":["Modern dental treatments are often painful, which is why many people refuse to visit the dentist.","Fear of pain keeps many people away from the dentist, although today's treatments are generally fast and cause very little pain.","Many people visit the dentist often because modern treatments are quick and almost painless.","Few people are afraid of the dentist today, since modern treatments have become quick and almost painless."],"a":1,"ex":"«even though» הוחלף ב-«although» (שתיהן: למרות ש), ו-«avoid going» הוחלף ב-«keeps away». הפחד מרחיק אנשים למרות שהטיפולים כמעט לא כואבים. בתשובה הראשונה הטיפולים כואבים, וזה ההפך מהמקור.","w":[["even though","אף על פי ש..."],["although","למרות ש..."],["avoid","להימנע מ..."]]},{"q":"The company decided to improve its training program after a survey showed that new workers did not understand many of their basic tasks.","o":["A survey found that new workers understood their basic tasks well, so the company kept its training program as it was.","The company improved its training program, and as a result, new workers began to complete a survey about their tasks.","New workers asked the company to cancel its training program because they already understood their basic tasks.","When a survey revealed that new employees were confused about many basic duties, the company chose to make its training better."],"a":3,"ex":"קודם הסקר הראה שהעובדים לא מבינים, ורק אחר כך החברה החליטה לשפר את ההדרכה. «improve» = «make better», ו-«did not understand» = «were confused». בתשובה השנייה הסדר הפוך: הסקר מופיע כתוצאה של השיפור.","w":[["improve","לשפר"],["after","אחרי"],["survey","סקר"]]},{"q":"Ancient sailors could cross wide seas without modern tools, since they learned to read the positions of the sun and the stars.","o":["Because they knew how to use the sun and stars to guide them, sailors long ago were able to travel across large seas without modern equipment.","Sailors long ago could not cross wide seas, because they had no modern tools to guide them.","Ancient sailors used modern tools to study the sun and the stars before they crossed wide seas.","Although ancient sailors studied the sun and the stars, this knowledge rarely helped them cross wide seas."],"a":0,"ex":"«since» כאן = מכיוון ש, ובתשובה הנכונה הוא הוחלף ב-«Because». «Ancient» = «long ago», ו-«tools» = «equipment». התשובה האחרונה הופכת את הסיבה לניגוד ואומרת שהידע כמעט לא עזר.","w":[["since","מכיוון ש..."],["ancient","עתיק, מימי קדם"],["rarely","לעיתים רחוקות"]]}]},{"type":"sc","qs":[{"q":"The road to the village was blocked by snow; ___, the doctor had to reach the patient by helicopter.","o":["however","for example","therefore","in contrast"],"a":2,"ex":"«therefore» = לכן. הכביש חסום, ולכן הרופא הגיע במסוק: זו תוצאה. «however» (עם זאת) היה יוצר ניגוד, אבל אין כאן ניגוד.","w":[["therefore","לכן"],["however","עם זאת, אולם"],["block","לחסום"]]},{"q":"Many drivers leave home before 7 a.m. in order to ___ the heavy traffic that fills the roads later in the morning.","o":["avoid","enjoy","create","measure"],"a":0,"ex":"«avoid» = להימנע מ. נהגים יוצאים מוקדם כדי לא להיתקע בפקקים. «create» (ליצור) או «enjoy» (ליהנות) לא מתאימים, כי אף אחד לא יוצא מוקדם כדי ליצור פקקים או ליהנות מהם.","w":[["avoid","להימנע מ..."],["in order to","כדי ל... (+פועל)"]]},{"q":"The new medicine must be tested on thousands of patients before doctors can ___ that it is safe.","o":["forget","hide","doubt","confirm"],"a":3,"ex":"«confirm» = לאשר, לוודא. בודקים את התרופה על אלפי חולים כדי לדעת בוודאות שהיא בטוחה. «doubt» (לפקפק) הוא ההפך: לא עושים ניסויים ארוכים כדי להתחיל לפקפק.","w":[["confirm","לאשר, לוודא"],["doubt","לפקפק"]]},{"q":"The old bus was so ___ that it broke down almost every week, and passengers often arrived late.","o":["popular","unreliable","expensive","comfortable"],"a":1,"ex":"«unreliable» = לא אמין. אוטובוס שמתקלקל כל שבוע ומאחר הוא לא אמין. «so ... that» (כל כך... ש) מחייב שהתכונה תסביר את התקלות, ו-«popular» או «comfortable» לא מסבירים אותן.","w":[["unreliable","לא אמין"],["so... that","כל כך... ש..."],["break down","להתקלקל"]]}]}]},{"id":"s2","title":"סימולציה 2 · בסיס+","level":1,"hi":122,"chapters":[{"type":"sc","qs":[{"q":"Many students are ___ to ask questions in class because they are afraid of looking foolish.","o":["reluctant","eager","proud","certain"],"a":0,"ex":"«Reluctant» = לא ששׂ, מהסס. הסיבה (הם מפחדים להיראות טיפשים) מסבירה למה הם לא רוצים לשאול. «Eager» (להוט) הוא ההפך ולא מתאים לפחד.","w":[["reluctant","מסרב, לא ששׂ"],["eager","להוט"],["because","כי, מפני ש..."]]},{"q":"Tom prefers quiet mornings, ___ his sister enjoys loud music as soon as she wakes up.","o":["so that","whereas","as a result","because"],"a":1,"ex":"«Whereas» = ואילו. משווים בין שני אנשים שונים: טום אוהב שקט, ואילו אחותו אוהבת מוזיקה רועשת. «Because» היה אומר שהמוזיקה שלה היא הסיבה שהוא אוהב שקט, וזה לא מה שהמשפט אומר.","w":[["whereas","בעוד ש..., ואילו"],["as soon as","ברגע ש..., מיד כש..."]]},{"q":"The number of people who smoke has ___ steadily over the last twenty years, thanks to strong public health campaigns.","o":["increased","doubled","declined","appeared"],"a":2,"ex":"«Declined» = ירד. קמפיינים לבריאות הציבור אמורים להוריד את מספר המעשנים, ו«thanks to» (בזכות) מראה שזו תוצאה טובה. «Increased» ו«doubled» (עלה, הכפיל את עצמו) הם תוצאה רעה, ולא מתאימים ל«בזכות».","w":[["decline","לרדת, לפחות"],["thanks to","הודות ל..., בזכות"],["steadily","בהתמדה, בהדרגה"]]},{"q":"You should save your work every few minutes; ___, you may lose everything if the computer crashes.","o":["moreover","similarly","for instance","otherwise"],"a":3,"ex":"«Otherwise» = אחרת. אם לא תשמור, תאבד הכול. החלק השני מתאר מה יקרה אם לא נעשה את מה שבחלק הראשון. «Moreover» (יתרה מזאת) רק מוסיף מידע ולא מתאים לאזהרה.","w":[["otherwise","אחרת"],["moreover","יתרה מזאת"]]}]},{"type":"sc","qs":[{"q":"The museum staff check the temperature in each room every day to ___ that the old paintings are not damaged.","o":["doubt","ensure","forget","deny"],"a":1,"ex":"«Ensure» = לוודא, להבטיח. הצוות בודק את הטמפרטורה כדי לוודא שהציורים לא ייפגעו. «Doubt» (לפקפק) ו«deny» (להכחיש) לא מסבירים למה בודקים כל יום.","w":[["ensure","לוודא, להבטיח"],["damage","לגרום נזק"]]},{"q":"___ the long delay at the airport, the passengers remained calm and polite.","o":["Despite","Because of","Instead of","In addition to"],"a":0,"ex":"«Despite» = למרות. עיכוב ארוך בדרך כלל מעצבן, ובכל זאת הנוסעים נשארו רגועים: זה ניגוד. «Because of» היה אומר שהעיכוב גרם להם להיות רגועים, וזה לא הגיוני.","w":[["despite","למרות (+שם עצם)"],["because of","בגלל (+שם עצם)"],["remain","להישאר"]]},{"q":"Snow is ___ in this part of the country; most people who live here have seen it only once or twice in their lives.","o":["common","heavy","welcome","rare"],"a":3,"ex":"«Rare» = נדיר. אם רוב התושבים ראו שלג רק פעם או פעמיים, השלג נדיר שם. «Common» (נפוץ) ו«heavy» (כבד) סותרים את החלק השני של המשפט.","w":[["rare","נדיר"],["common","נפוץ"]]},{"q":"You may borrow my car this weekend, ___ you return it with a full tank of gas.","o":["even though","whereas","provided that","so that"],"a":2,"ex":"«Provided that» = בתנאי ש. מותר לקחת את הרכב בתנאי שתחזיר אותו עם מיכל מלא. «Even though» (אף על פי ש) מראה ניגוד, ואין כאן ניגוד אלא תנאי.","w":[["provided that","בתנאי ש..."],["even though","אף על פי ש..."]]}]},{"type":"rc","title":"From Private Shelves to Public Spaces","text":["For most of history, books were rare and expensive. Before the invention of the printing press, each copy had to be written by hand, a process that could take months. As a result, collections of books belonged mainly to kings, religious institutions and wealthy families. Ordinary people were seldom allowed to enter these collections, and many of them could not read in any case.","This situation began to change in the nineteenth century. As cities grew and more children attended school, reformers argued that knowledge should not be limited to the rich. They believed that a free library would help workers improve themselves and become better citizens. In the middle of the century, Britain passed a law that allowed towns to use public money to open libraries, and the United States soon followed. Some officials were reluctant to spend tax money on books, but the idea gradually spread.","For about a hundred years, the main role of the public library was simple: to lend books and to provide a quiet place to read. In the late twentieth century, however, this role was challenged. Television, and later the internet, gave people new ways to find information and entertainment. Many experts predicted that the number of visitors would decline and that libraries would eventually disappear.","That prediction has not come true. Instead, libraries have changed their role. Today, many of them offer free internet access, classes in computer skills and help for people who are looking for work. In addition, they serve as meeting places for local groups and as safe spaces for children after school. Whereas the early library was mainly a storehouse of books, the modern library is closer to a community center. Its goal, however, remains the same: to ensure that everyone, whatever their income, has access to knowledge."],"qs":[{"q":"The passage mainly discusses","o":["why the printing press made books cheaper","why the internet will soon replace public libraries","how public libraries began and how their role has changed over time","the differences between libraries in Britain and the United States"],"a":2,"ex":"הקטע עובר מההיסטוריה (ספרים נדירים, ספריות ציבוריות במאה ה-19) אל השינוי בתפקיד הספרייה היום. האפשרות על האינטרנט סותרת את הפסקה האחרונה, שאומרת שהתחזית לא התגשמה.","w":[["role","תפקיד"],["mainly","בעיקר"]]},{"q":"According to the first paragraph, collections of books belonged mainly to the rich because","o":["books were copied slowly by hand and were therefore expensive","the law did not allow ordinary people to buy books","religious institutions refused to share their books","most ordinary people preferred to listen to stories"],"a":0,"ex":"בפסקה 1: כל עותק נכתב ביד ולקח חודשים, ולכן «As a result» הספרים היו של מלכים ועשירים. אין בפסקה שום חוק שאסר לקנות ספרים.","w":[["as a result","כתוצאה מכך"],["wealthy","עשיר"],["seldom","לעיתים רחוקות"]]},{"q":"In the second paragraph, the word 'They' (in 'They believed that...') refers to","o":["cities","children","workers","reformers"],"a":3,"ex":"המשפט הקודם אומר ש«reformers» (אנשי רפורמה) טענו שידע לא צריך להיות רק לעשירים, והם אלה ש«האמינו» שספרייה חינמית תעזור לפועלים. «Workers» מופיעים באותו משפט, אבל הם מי שעוזרים לו, לא מי שמאמין.","w":[["reformer","מתקן חברתי, איש רפורמה"],["argue","לטעון"]]},{"q":"According to the third paragraph, many experts expected that","o":["television would make people read more books","libraries would lose visitors and finally close","libraries would start to lend computers","the number of public libraries would grow quickly"],"a":1,"ex":"בפסקה 3 כתוב שהמומחים חזו שמספר המבקרים «would decline» (ירד) ושהספריות «would eventually disappear» (ייעלמו בסוף). «Grow quickly» הוא ההפך.","w":[["predict","לחזות"],["eventually","בסופו של דבר"],["decline","לרדת, לפחות"]]},{"q":"The main purpose of the last paragraph is to","o":["explain why the experts' prediction was correct","describe how libraries have adapted to people's new needs","argue that libraries should stop lending books","compare libraries in poor and rich neighborhoods"],"a":1,"ex":"הפסקה האחרונה מתארת מה הספריות מציעות היום (אינטרנט, קורסים, מקום מפגש) כלומר איך הן השתנו. היא פותחת במילים «That prediction has not come true», ולכן היא לא מסבירה שהתחזית הייתה נכונה.","w":[["instead","במקום זאת"],["in addition","בנוסף"],["whereas","בעוד ש..., ואילו"]]}]},{"type":"rs","qs":[{"q":"Although the new highway shortened the trip to the city, many local residents were unhappy with it because it brought noise and pollution to their neighborhood.","o":["Because the new highway made the trip to the city shorter, local residents were pleased with it in spite of the noise and pollution.","Many local residents opposed the new highway because it made the trip to the city longer and their area noisier.","The new highway made the trip to the city shorter; nevertheless, many people living nearby disliked it, since it caused noise and pollution in their area.","The noise and pollution in the neighborhood were caused by local residents who used the new highway to travel to the city."],"a":2,"ex":"במקור: הכביש קיצר את הדרך, ובכל זאת התושבים לא מרוצים בגלל רעש וזיהום. «nevertheless» שומר על אותו ניגוד כמו «Although». התשובה הראשונה הופכת את המשמעות (התושבים מרוצים), והשנייה אומרת שהדרך התארכה.","w":[["although","למרות ש... (+משפט)"],["nevertheless","למרות זאת, אף על פי כן"],["resident","תושב"]]},{"q":"Scientists rarely agree on the exact causes of climate change in a particular region, since local weather is influenced by many factors at the same time.","o":["Because many factors affect local weather simultaneously, scientists seldom reach agreement about what exactly causes climate change in a specific region.","Scientists usually agree on the exact causes of climate change in a region, even though local weather is affected by many factors.","Since scientists rarely agree with each other, local weather in a particular region is influenced by many different factors.","Scientists rarely study local weather, because climate change in a particular region has only one main cause."],"a":0,"ex":"«rarely» = «seldom» (לעיתים רחוקות), ו«since» = «because» (מכיוון ש). התשובה השנייה משנה את «rarely» ל«usually», והשלישית הופכת סיבה ותוצאה: כאילו חוסר ההסכמה גורם למזג האוויר.","w":[["rarely","לעיתים רחוקות"],["seldom","לעיתים רחוקות"],["simultaneously","בו זמנית"]]},{"q":"Unless the city council finds additional funding by the end of the year, the plan to build a new public swimming pool will be canceled.","o":["The city council will find additional funding by the end of the year, so the new public swimming pool will be built.","Even if the city council finds more money by the end of the year, the plan for the new swimming pool will be canceled.","The plan to build a new swimming pool was canceled because the city council spent its money before the end of the year.","The plan for a new public swimming pool will be canceled if the city council does not find more money before the year ends."],"a":3,"ex":"«Unless» = אלא אם כן, כלומר «if ... not». התוכנית תבוטל אם לא יימצא כסף. «Even if» (גם אם) אומר שהיא תבוטל בכל מקרה, וזו משמעות אחרת. התשובה הראשונה טוענת בוודאות שהכסף יימצא, וזה לא כתוב במקור.","w":[["unless","אלא אם כן"],["even if","גם אם, אפילו אם"],["funding","מימון"]]}]},{"type":"rs","qs":[{"q":"Unlike earlier studies, the new research found that children who read for pleasure every day also tend to perform better in mathematics.","o":["Like earlier studies, the new research found that children who are good at mathematics usually enjoy reading every day.","Unlike earlier studies, the new research found that children who read every day for pleasure tend to do worse in mathematics.","Earlier studies found that daily reading improves mathematics, but the new research found no connection between the two.","The new research, unlike previous studies, showed that children who read for enjoyment every day generally do better in math as well."],"a":3,"ex":"«Unlike» = בניגוד ל. רק המחקר החדש מצא שילדים שקוראים להנאה כל יום מצליחים יותר במתמטיקה. התשובה השנייה משנה «better» ל«worse», והשלישית מחליפה בין המחקר החדש למחקרים הקודמים.","w":[["unlike","בניגוד ל... (+שם עצם)"],["tend to","נוטה ל..."],["perform","לבצע, להצליח (במשימה)"]]},{"q":"Demand for the company's products grew rapidly in the north; as a result, the company decided to open a second factory in that region.","o":["The company decided to open another factory in the north because demand for its products in that area had increased quickly.","Because the company opened a second factory in the north, demand for its products in that region grew rapidly.","Although demand for its products grew in the north, the company decided not to open a second factory there.","The company closed its factory in the north and opened a second one elsewhere, since demand in the north was falling."],"a":0,"ex":"במקור: הביקוש עלה (סיבה), ולכן נפתח מפעל שני (תוצאה). «because» בתשובה הנכונה שומר על אותו סדר הגיוני. התשובה השנייה הופכת סיבה ותוצאה: כאילו המפעל גרם לביקוש.","w":[["as a result","כתוצאה מכך"],["demand","ביקוש"],["rapidly","במהירות"]]},{"q":"Despite being one of the oldest buildings in town, the library is visited by hundreds of young people every week, many of whom come to study for exams.","o":["Because the library is one of the oldest buildings in town, very few young people visit it, except to study for exams.","Hundreds of young people visit the library every week in order to see one of the oldest buildings in town.","Although the library is among the oldest buildings in town, hundreds of young people go there each week, and many of them study for their exams there.","The library, which was built only recently, is visited every week by hundreds of young people who study for exams."],"a":2,"ex":"«Despite» = «Although» (למרות). הבניין ישן, ובכל זאת מאות צעירים מגיעים, ורבים מהם לומדים למבחנים. התשובה הראשונה אומרת שמעט מבקרים, והרביעית אומרת שהבניין חדש.","w":[["despite","למרות (+שם עצם)"],["although","למרות ש... (+משפט)"],["in order to","כדי ל... (+פועל)"]]}]},{"type":"sc","qs":[{"q":"Driving while very tired can have serious ___, such as accidents that hurt both the driver and other people on the road.","o":["benefits","consequences","habits","reasons"],"a":1,"ex":"«Consequences» = השלכות, תוצאות. תאונות הן תוצאה של נהיגה בעייפות. «Benefits» (יתרונות) הוא ההפך, ו«reasons» (סיבות) לא מתאים כי התאונה באה אחרי הנהיגה ולא לפניה.","w":[["consequence","תוצאה, השלכה"],["such as","כגון, כמו"],["benefit","יתרון, תועלת"]]},{"q":"The old bridge was in such poor ___ that the city closed it to traffic until the repairs were finished.","o":["condition","position","attention","opinion"],"a":0,"ex":"«Condition» = מצב. הגשר היה במצב כל כך גרוע שסגרו אותו עד סוף התיקונים. «Position» (מיקום) לא מסביר למה צריך תיקונים.","w":[["condition","מצב"],["so... that","כל כך... ש..."],["until","עד ש..."]]},{"q":"Because the road was icy, the driver tried to ___ sudden stops, which could cause the car to slide.","o":["practice","enjoy","require","avoid"],"a":3,"ex":"«Avoid» = להימנע מ. עצירות פתאומיות על כביש קפוא מסוכנות, ולכן הנהג ניסה להימנע מהן. «Practice» (להתאמן) או «enjoy» (ליהנות) לא הגיוניים כשמדובר בסכנה.","w":[["avoid","להימנע מ..."],["because","כי, מפני ש... (+משפט)"]]},{"q":"The team trained hard for months; ___, they won the national championship for the first time.","o":["nevertheless","for instance","as a result","in contrast"],"a":2,"ex":"«As a result» = כתוצאה מכך. האימונים הקשים (סיבה) הובילו לזכייה (תוצאה). «Nevertheless» (למרות זאת) מתאים רק כשיש ניגוד, ואין ניגוד בין אימון קשה לניצחון.","w":[["as a result","כתוצאה מכך"],["nevertheless","למרות זאת, אף על פי כן"]]}]}]},{"id":"s3","title":"סימולציה 3 · בינוני","level":2,"hi":132,"chapters":[{"type":"sc","qs":[{"q":"Scientists warn that, unless action is taken soon, the loss of several coral reefs will become ___.","o":["reversible","voluntary","inevitable","temporary"],"a":2,"ex":"«inevitable» = בלתי נמנע. המדענים מזהירים שאם לא יפעלו מהר, האובדן של השוניות כמעט בטוח יקרה. «reversible» (הפיך) הפוך מהכוונה של האזהרה.","w":[["inevitable","בלתי נמנע"],["unless","אלא אם כן"]]},{"q":"The museum's new exhibition received poor reviews from critics; ___, it attracted a record number of visitors.","o":["nevertheless","consequently","similarly","for instance"],"a":0,"ex":"«nevertheless» = למרות זאת. הביקורות היו רעות, ובכל זאת הגיע מספר שיא של מבקרים: יש כאן ניגוד. «consequently» (כתוצאה מכך) לא מתאים, כי ביקורות רעות לא גורמות לשיא מבקרים.","w":[["nevertheless","למרות זאת, אף על פי כן"],["record","שיא"]]},{"q":"Rising rents have forced many young families to leave the city center, a trend that threatens to ___ the area's sense of community.","o":["strengthen","celebrate","imitate","undermine"],"a":3,"ex":"«undermine» = לערער, להחליש. עזיבת המשפחות הצעירות פוגעת בתחושת הקהילה, ולכן המגמה «מאיימת לערער» אותה. «strengthen» (לחזק) הפוך: מגמה מאיימת לא מחזקת.","w":[["undermine","לערער, להחליש"],["threaten","לאיים"]]},{"q":"Few of the volunteers could afford a car, ___ a house of their own.","o":["rather than","let alone","in order to","as well as"],"a":1,"ex":"«let alone» = ובטח שלא, קל וחומר. רובם לא יכלו להרשות לעצמם אפילו מכונית, ובטח שלא בית, שהוא יקר הרבה יותר. «as well as» (וגם) לא מוסיף את הרעיון של «ובטח שלא», שהוא כל הטעם של המשפט.","w":[["let alone","ובטח שלא, קל וחומר"],["afford","להרשות לעצמו (כלכלית)"]]}]},{"type":"sc","qs":[{"q":"The professor's theory was once rejected by most of her colleagues, but today it enjoys ___ support across the field.","o":["reluctant","widespread","scarce","hidden"],"a":1,"ex":"«widespread» = נפוץ, רחב. פעם רוב העמיתים דחו את התיאוריה, «but» היום היא נהנית מתמיכה רחבה: זה הניגוד ש-«but» דורש. «scarce» (מועט) לא יוצר ניגוד לעבר.","w":[["widespread","נפוץ, רחב היקף"],["reject","לדחות"]]},{"q":"The northern region receives heavy rainfall throughout the year, ___ the south remains dry for most months.","o":["so that","because","unless","whereas"],"a":3,"ex":"«whereas» = ואילו, בעוד ש. משווים בין הצפון הגשום לדרום היבש, כלומר ניגוד בין שני צדדים. «because» היה אומר שהגשם בצפון גורם ליובש בדרום, וזה לא הגיוני.","w":[["whereas","בעוד ש..., ואילו"],["throughout","לאורך, במשך כל"]]},{"q":"Children who grow up speaking two languages often ___ a third one more easily than those who speak only one.","o":["acquire","abandon","ignore","conceal"],"a":0,"ex":"«acquire» = לרכוש (ידע, שפה). ילדים דו-לשוניים לומדים שפה שלישית בקלות רבה יותר. «abandon» (לנטוש) לא מתאים ל-«more easily» ולהקשר של יתרון.","w":[["acquire","לרכוש"],["abandon","לנטוש, לזנוח"]]},{"q":"The bridge had not been inspected for over a decade; ___, nobody was surprised when engineers declared it unsafe.","o":["in contrast","even so","consequently","otherwise"],"a":2,"ex":"«consequently» = כתוצאה מכך. הגשר לא נבדק יותר מעשר שנים, ולכן אף אחד לא הופתע שהוכרז מסוכן: סיבה ותוצאה. «even so» (למרות זאת) היה רומז שהיה צפוי שיופתעו, וזה הפוך.","w":[["consequently","כתוצאה מכך, לפיכך"],["inspect","לבדוק, לפקח"]]}]},{"type":"rc","title":"The Story That Changes Each Time","text":["Most people assume that a memory works like a recording: once an event is stored, it can be played back whenever it is needed. Psychologists who study memory, however, have found that this common belief is largely mistaken. Rather than retrieving a fixed copy, the brain rebuilds an experience each time we recall it, using fragments of the original event together with our current knowledge, feelings and expectations. As a result, a story that we have told many times may differ substantially from what actually happened.","One explanation for this effect is a process known as reconsolidation. When a memory is brought to mind, it becomes unstable for a short period before it is stored again. During this window, new information can be added and old details can be lost. If, for example, a listener reacts with surprise to a particular part of a story, the speaker may emphasize that part the next time and gradually drop details that seemed less interesting. Each retelling, in other words, becomes the new \"original.\"","Experiments support this idea. In one type of study, volunteers watch a short film and are later asked to describe it to different listeners. Those who describe it to a listener who is believed to dislike the main character tend to present that character more negatively. Weeks later, even when asked to recall the film itself rather than their own description, they still remember the character in the less favorable way. Their memory has apparently been shaped by the version they chose to tell.","These findings have important consequences. In courts, witnesses who have repeated their account many times may feel highly confident even though their memories have shifted. Nevertheless, researchers stress that the flexibility of memory is not simply a flaw. A system that constantly updates itself allows people to connect past experiences to new situations and to learn from them. The price of this flexibility is that our most cherished stories are, to some degree, always being rewritten."],"qs":[{"q":"Which of the following is the best title for the passage?","o":["Why Children Forget Their Early Years","How Retelling a Story Reshapes Our Memories","The Role of Witnesses in Modern Courts","A Simple Method for Improving Memory"],"a":1,"ex":"הקטע כולו עוסק בכך שכל פעם שמספרים סיפור, הזיכרון נבנה מחדש ומשתנה. עדים בבית משפט מוזכרים רק בפסקה האחרונה כדוגמה, ולכן זו לא כותרת לכל הקטע.","w":[["retell","לספר מחדש"],["reshape","לעצב מחדש"]]},{"q":"According to the second paragraph, while a memory is being recalled, it","o":["is permanently erased from the brain","becomes more accurate than before","is passed on unchanged to the listener","can be altered before it is stored again"],"a":3,"ex":"בפסקה 2 כתוב שכשנזכרים, הזיכרון «becomes unstable» לזמן קצר לפני שהוא נשמר שוב, ובחלון הזה אפשר להוסיף פרטים ולאבד אחרים. אין שם טענה שהוא נמחק לגמרי או נעשה מדויק יותר.","w":[["unstable","לא יציב"],["alter","לשנות"]]},{"q":"In paragraph 3, the word \"Their\" (in \"Their memory has apparently been shaped\") refers to","o":["the listeners","the main characters","the volunteers","the films"],"a":2,"ex":"המשפט מתאר את המתנדבים שתיארו את הסרט, ושאחרי שבועות זכרו את הדמות באופן שלילי יותר. «Their memory» = הזיכרון של המתנדבים. המאזינים לא זוכרים את הסרט, כי הם לא ראו אותו.","w":[["volunteer","מתנדב"],["apparently","ככל הנראה"]]},{"q":"What does the experiment described in paragraph 3 suggest?","o":["The way people describe an event can later change how they remember it.","People remember films more accurately than real-life events.","Listeners usually adopt the speaker's opinion of a character.","Volunteers deliberately lied in order to please their listeners."],"a":0,"ex":"המתנדבים שתיארו את הדמות באופן שלילי זכרו אותה כך גם שבועות אחר כך, «even when asked to recall the film itself». כלומר הגרסה שסיפרו שינתה את הזיכרון. לא נאמר שהם שיקרו בכוונה.","w":[["favorable","חיובי, אוהד"],["deliberately","בכוונה"]]},{"q":"The main purpose of the last paragraph is to","o":["describe a new experiment carried out on witnesses","prove that human memory should never be trusted","point out both a practical risk and an advantage of memory's flexibility","argue that courts should stop relying on witnesses"],"a":2,"ex":"הפסקה האחרונה מציגה סיכון (עדים בטוחים בעצמם למרות שהזיכרון שלהם השתנה), ואז «Nevertheless» מביאה יתרון: גמישות שמאפשרת ללמוד. «should never be trusted» קיצוני מדי, כי נאמר במפורש שזה «not simply a flaw».","w":[["nevertheless","למרות זאת, אף על פי כן"],["flaw","פגם"]]}]},{"type":"rs","qs":[{"q":"Although the new medication reduced symptoms in most patients, doctors remain cautious because its long-term effects have not yet been studied in sufficient depth.","o":["Because the new medication reduced symptoms in most patients, doctors are confident that its long-term effects will be safe.","The new medication helped only a few patients, so doctors will remain cautious until its long-term effects are studied in depth.","Doctors have stopped prescribing the new medication, since studies have shown that its long-term effects are harmful.","Doctors are still careful about the new medication, even though it helped most patients, since not enough research has been done on its long-term effects."],"a":3,"ex":"במקור: התרופה עזרה לרוב החולים, אבל הרופאים זהירים כי ההשפעות ארוכות הטווח לא נחקרו מספיק. התשובה הנכונה מחליפה «Although» ב-«even though» ומשנה את סדר החלקים. «only a few patients» משנה את הכמות (במקור «most»).","w":[["cautious","זהיר"],["even though","אף על פי ש..."],["sufficient","מספיק"]]},{"q":"The ancient city was eventually abandoned, not because of a sudden invasion, as was once widely believed, but as a result of a slow decline in its water supply.","o":["Contrary to a once common view, it was a gradual shortage of water, rather than an unexpected attack, that finally led people to leave the ancient city.","The ancient city was abandoned after a sudden invasion, which also damaged its water supply.","Many people once believed that the ancient city had a serious water problem, but it was actually destroyed by invaders.","Although its water supply was declining slowly, the ancient city was never abandoned by its people."],"a":0,"ex":"במקור: העיר ננטשה לא בגלל פלישה, כפי שחשבו פעם, אלא בגלל ירידה איטית באספקת המים. התשובה הנכונה אומרת את זה עם «rather than» ועם «Contrary to a once common view». האפשרויות על הפולשים הופכות את הסיבה.","w":[["abandon","לנטוש"],["as a result of","כתוצאה מ..."],["rather than","במקום, ולא"]]},{"q":"Few employees took advantage of the flexible working hours, since most of them feared that their managers would regard it as a lack of commitment.","o":["Many employees used the flexible working hours, although they feared that their managers would view it as a lack of commitment.","Worried that their managers might see it as a sign of low commitment, only a small number of employees made use of the flexible working hours.","Most managers feared that employees who used the flexible hours would show a lack of commitment, so they cancelled the option.","Because their managers considered them uncommitted, few employees were offered flexible working hours."],"a":1,"ex":"«Few» = מעט מאוד עובדים השתמשו בשעות הגמישות, כי פחדו שהמנהלים יראו בזה חוסר מחויבות. התשובה הנכונה מעבירה את הסיבה לתחילת המשפט ואומרת «only a small number». «Many employees» הופך את הכמות.","w":[["few","מעט (כמעט אין)"],["take advantage of","לנצל, להשתמש ב..."],["commitment","מחויבות"]]}]},{"type":"rs","qs":[{"q":"Even though online courses are cheaper and more convenient, many students still prefer traditional classes, in which they can interact directly with teachers and classmates.","o":["Because online courses are cheaper and more convenient, most students have stopped attending traditional classes.","Many students prefer online courses, since these allow them to interact directly with teachers and classmates.","Many students continue to choose traditional classes, where face-to-face contact with teachers and other students is possible, despite the lower cost and greater convenience of online courses.","Traditional classes are cheaper than online courses, so many students still prefer them in order to meet their teachers."],"a":2,"ex":"במקור: למרות שקורסים מקוונים זולים ונוחים יותר, הרבה סטודנטים עדיין מעדיפים כיתות רגילות, שבהן יש קשר ישיר עם המרצים. התשובה הנכונה מחליפה «Even though» ב-«despite» ומעבירה אותו לסוף. האפשרות הראשונה הופכת את הוויתור לסיבה.","w":[["even though","אף על פי ש..."],["despite","למרות (+שם עצם)"],["still","ובכל זאת; עדיין"]]},{"q":"The government introduced a tax on sugary drinks so as to reduce their consumption, and within two years, sales of such drinks had fallen considerably.","o":["The government introduced a tax on sugary drinks because their sales had fallen considerably over the previous two years.","In order to cut the consumption of sugary drinks, a tax was placed on them by the government; within two years, their sales had dropped significantly.","Although the government taxed sugary drinks in order to reduce their consumption, sales of these drinks hardly changed within two years.","Drink companies raised the price of sugary drinks so as to reduce their consumption, and sales fell considerably within two years."],"a":1,"ex":"במקור: הממשלה הטילה מס על משקאות ממותקים כדי להפחית את הצריכה, ותוך שנתיים המכירות ירדו מאוד. התשובה הנכונה עוברת לסביל («a tax was placed on them by the government») ו-«so as to» הופך ל-«In order to». באפשרות הראשונה הירידה במכירות היא הסיבה למס, וזה הפוך.","w":[["so as to","כדי ל..."],["in order to","כדי ל... (+פועל)"],["considerably","במידה ניכרת"]]},{"q":"Whereas earlier researchers relied mainly on questionnaires, today's scientists can observe brain activity directly, which allows them to test theories that were once impossible to examine.","o":["Both earlier and modern researchers have relied mainly on questionnaires, which is why some theories still cannot be tested.","Today's scientists rely mainly on questionnaires, since observing brain activity directly has turned out to be impossible.","Earlier researchers observed brain activity directly, whereas today's scientists prefer questionnaires in order to test new theories.","Unlike researchers in the past, who depended mostly on questionnaires, modern scientists are able to watch the brain at work, and this lets them check theories that could not be tested before."],"a":3,"ex":"במקור: חוקרים בעבר הסתמכו בעיקר על שאלונים, ואילו היום אפשר לצפות במוח ישירות ולבדוק תיאוריות שלא היה אפשר לבדוק קודם. התשובה הנכונה מחליפה «Whereas» ב-«Unlike». האפשרות השלישית מחליפה בין העבר להווה.","w":[["whereas","בעוד ש..., ואילו"],["unlike","בניגוד ל... (+שם עצם)"],["rely","להסתמך"]]}]},{"type":"sc","qs":[{"q":"The two reports differ ___ in their conclusions: one predicts steady growth, while the other predicts a deep recession.","o":["substantially","slightly","barely","equally"],"a":0,"ex":"«substantially» = באופן משמעותי. דוח אחד צופה צמיחה והשני מיתון עמוק, כלומר הבדל גדול. «slightly» (מעט) ו-«barely» (בקושי) סותרים את ההבדל החד שמתואר אחרי הנקודתיים.","w":[["substantially","באופן משמעותי, ניכר"],["recession","מיתון"]]},{"q":"The athlete continued to train every morning ___ she had been told by her doctor to rest.","o":["so that","as long as","even though","in case"],"a":2,"ex":"«even though» = אף על פי ש. הרופא אמר לה לנוח, ובכל זאת היא המשיכה להתאמן: ויתור. «as long as» (כל עוד) היה הופך את הוראת הרופא לתנאי לאימון, וזה לא הגיוני.","w":[["even though","אף על פי ש..."],["as long as","כל עוד, בתנאי ש..."]]},{"q":"Since the original documents were destroyed in a fire, historians are forced to ___ later copies whose accuracy cannot be fully confirmed.","o":["do without","dispose of","apply for","rely on"],"a":3,"ex":"«rely on» = להסתמך על. המסמכים המקוריים נשרפו, ולכן ההיסטוריונים נאלצים להסתמך על העותקים המאוחרים. «do without» (להסתדר בלי) הפוך: אין להם ברירה אלא להשתמש בעותקים.","w":[["rely on","להסתמך על"],["accuracy","דיוק"]]},{"q":"Many students record their lectures ___ review the material later at their own pace.","o":["let alone","so as to","rather than","so as not to"],"a":1,"ex":"«so as to» = כדי ל. מקליטים את ההרצאה כדי לחזור על החומר אחר כך: מטרה. «so as not to» אומר «כדי לא לחזור על החומר», וזה הפוך מהסיבה שמקליטים. «rather than» (במקום) ו-«let alone» (ועל אחת כמה וכמה לא) לא מתאימים למשמעות.","w":[["so as to","כדי ל..."],["at one's own pace","בקצב של עצמו"]]}]}]},{"id":"s4","title":"סימולציה 4 · מתקדם","level":3,"hi":142,"chapters":[{"type":"sc","qs":[{"q":"Because fresh water had become ___ in the region after three dry winters, farmers were forced to ration it among their crops.","o":["abundant","transparent","scarce","fragile"],"a":2,"ex":"«scarce» = נדיר, מועט. אחרי שלושה חורפים יבשים יש מעט מים, ולכן החקלאים נאלצו לחלק אותם במנות. «abundant» (בשפע) הוא ההפך: אם היו מים בשפע לא היה צורך לקצוב אותם.","w":[["scarce","נדיר, מועט"],["ration","לחלק במנות קצובות"],["abundant","שופע, בשפע"]]},{"q":"___ the strong objections of local residents, the city council voted to build the new highway along the river.","o":["Notwithstanding","Owing to","In view of","By virtue of"],"a":0,"ex":"«notwithstanding» = על אף, למרות. התושבים התנגדו, ובכל זאת המועצה הצביעה בעד הכביש: זה ניגוד, ולכן צריך מילת ויתור. «owing to» ו-«in view of» נותנים סיבה, וזה לא הגיוני שההתנגדות היא הסיבה לבנות.","w":[["notwithstanding","על אף, למרות"],["owing to","בשל, עקב"],["objection","התנגדות"]]},{"q":"Without regular maintenance, the old wooden bridge continued to ___ until engineers finally declared it unsafe for traffic.","o":["flourish","accelerate","comply","deteriorate"],"a":3,"ex":"«deteriorate» = להידרדר, להתבלות. גשר בלי תחזוקה הולך ומתקלקל עד שהוא לא בטוח. «flourish» (לשגשג) הוא ההפך הגמור.","w":[["deteriorate","להידרדר, להתבלות"],["maintenance","תחזוקה"],["flourish","לשגשג, לפרוח"]]},{"q":"The new drug lowered blood pressure in most of the patients who took it, ___ reducing their risk of suffering a heart attack.","o":["despite","thereby","instead of","unlike"],"a":1,"ex":"«thereby» = ובכך, על ידי כך. הורדת לחץ הדם היא הדרך שבה ירד הסיכון להתקף לב, כלומר זו תוצאה. «despite» (למרות) יוצר ניגוד שאין כאן, ו-«instead of» אומר שהסיכון לא ירד.","w":[["thereby","ובכך, על ידי כך"],["instead of","במקום"]]}]},{"type":"sc","qs":[{"q":"The lawyer's argument was so ___ that even the judge, who had seemed doubtful at first, was eventually persuaded.","o":["tedious","compelling","ambiguous","reluctant"],"a":1,"ex":"«compelling» = משכנע, חזק. הטיעון שכנע אפילו שופט שהיה בספק. «ambiguous» (דו-משמעי) הוא תכונה שמחלישה טיעון, לא כזו שמשכנעת.","w":[["compelling","משכנע, חזק"],["persuade","לשכנע"],["ambiguous","דו-משמעי"]]},{"q":"The museum agreed to lend the famous painting to the exhibition, ___ only for a limited period of three weeks.","o":["hence","whereby","lest","albeit"],"a":3,"ex":"«albeit» = אם כי. המוזיאון הסכים להשאיל, אבל עם הגבלה (רק לשלושה שבועות): זה ויתור חלקי. «hence» (ולכן) היה הופך את ההגבלה לתוצאה של ההסכמה, וזה לא הגיוני.","w":[["albeit","אם כי"],["hence","מכאן, ולכן"]]},{"q":"Planting trees along the river banks can ___ the damage caused by floods, although it cannot prevent flooding altogether.","o":["mitigate","intensify","precede","conceal"],"a":0,"ex":"«mitigate» = למתן, להקל. העצים מקטינים את הנזק, אבל (although) לא מונעים את השיטפון לגמרי. «intensify» (להגביר) הוא ההפך, ואז החלק השני עם «although» לא מתחבר.","w":[["mitigate","למתן, להקל"],["intensify","להגביר, להחריף"],["altogether","לגמרי"]]},{"q":"Unlike the old system, ___ every student was given exactly the same exam, the new program allows teachers to adapt tests to individual needs.","o":["whereas","thereby","whereby","hence"],"a":2,"ex":"«whereby» = שבאמצעותו, שלפיו. הוא מתאר את השיטה הישנה: שיטה שלפיה כל תלמיד קיבל אותו מבחן. «whereas» (בעוד ש) מוסיף ניגוד שני, אבל הניגוד כבר נאמר במילה «Unlike».","w":[["whereby","שבאמצעותו, שלפיו"],["whereas","בעוד ש..., ואילו"],["adapt","להתאים"]]}]},{"type":"rc","title":"Counting the Invisible: Microplastics in the Deep Sea","text":["For decades, public concern about plastic in the ocean focused on what could be seen: bottles floating on the surface and bags washed up on beaches. In recent years, however, researchers have turned their attention to the deep sea. Microplastics, fragments smaller than five millimeters, have been found in sediments thousands of meters below the surface, and even at the bottom of the deepest trenches. Many scientists now suspect that the ocean floor holds far more plastic than the surface does, although no one can yet say how much.","One reason for this uncertainty is that the deep sea is vast and expensive to reach. Collecting a single core of sediment may require a research ship, a trained crew and specialized equipment for several weeks. Hence, samples are scarce, and most come from a handful of locations that may not represent the ocean floor as a whole. Moreover, the particles themselves are tiny. The smallest cannot be seen even under an ordinary microscope, and all of them must first be separated from sand, shells and organic matter. This is a slow process whereby a sample is treated with chemicals, some of which can damage certain types of plastic and make them harder to identify.","A further difficulty is contamination. Researchers' clothing, their equipment and even the air in the laboratory constantly shed tiny plastic fibers. Unless strict precautions are taken, a sample may end up containing fibers from the laboratory, as opposed to the seabed. Several early studies were later found to have overestimated the amount of plastic for exactly this reason. Consequently, many laboratories now process 'blank' samples, containers of clean water handled in exactly the same way as the real ones, in order to estimate how much contamination occurs.","Notwithstanding these obstacles, accurate measurements matter. Microplastics on the seafloor may be swallowed by the creatures that live there and passed up the food chain. Some researchers argue that efforts to reduce plastic waste should not wait for precise figures; others caution that without reliable data it will be impossible to judge whether such efforts are working. Both groups agree, however, that standardized methods are needed so that results from different laboratories can be compared."],"qs":[{"q":"The main purpose of the passage is to","o":["argue that microplastics are more harmful in the deep sea than at the surface","describe a new technology for removing plastic from the ocean floor","show that all studies of deep-sea microplastics are unreliable","explain why the amount of microplastics in the deep sea is hard to determine"],"a":3,"ex":"כל הקטע עוסק בקשיים במדידה: המקום רחוק ויקר (פסקה 2), החלקיקים זעירים (פסקה 2), זיהום במעבדה (פסקה 3). הקטע לא משווה כמה הפלסטיק מזיק בכל מקום, ולא אומר שכל המחקרים לא אמינים, רק כמה מחקרים מוקדמים.","w":[["determine","לקבוע, לברר"],["unreliable","לא אמין"]]},{"q":"According to the second paragraph, one reason deep-sea samples may give a misleading picture is that","o":["they are collected from only a small number of places","the chemicals used to treat them add plastic particles","the particles in them are too large to separate from sand","research ships often lose them during long journeys"],"a":0,"ex":"בפסקה 2 כתוב שרוב הדגימות מגיעות מ-«a handful of locations» (מעט מקומות) שאולי לא מייצגים את כל קרקעית האוקיינוס. הכימיקלים לא מוסיפים פלסטיק, הם עלולים לפגוע בו, והחלקיקים זעירים ולא גדולים.","w":[["a handful of","קומץ, מעט"],["represent","לייצג"],["misleading","מטעה"]]},{"q":"In the third paragraph, the word 'shed' could best be replaced by","o":["store","hide","release","collect"],"a":2,"ex":"בגדים, ציוד ואוויר המעבדה «shed» סיבי פלסטיק, כלומר משחררים ומפזרים אותם, וכך הסיבים נכנסים לדגימות. «collect» (לאסוף) הוא כמעט ההפך: אם הם היו אוספים סיבים, לא היה זיהום.","w":[["shed","להשיר, לשחרר"],["release","לשחרר"],["contamination","זיהום"]]},{"q":"The third paragraph mainly serves to","o":["suggest that laboratory research on microplastics should be abandoned","point out a source of error in measurement and how scientists deal with it","compare the amount of plastic in clothing with the amount in the ocean","prove that early estimates of deep-sea plastic were too low"],"a":1,"ex":"פסקה 3 מציגה בעיה (זיהום מהמעבדה שמגדיל את הכמות שנמדדת) ואת הפתרון (דגימות «blank»). המחקרים המוקדמים העריכו יותר מדי (overestimated) ולא פחות מדי, ולכן התשובה האחרונה הפוכה.","w":[["overestimate","להעריך יותר מדי"],["consequently","כתוצאה מכך, לפיכך"],["as opposed to","בניגוד ל..."]]},{"q":"According to the last paragraph, researchers who disagree about when to act","o":["share the view that laboratories need common methods of measurement","agree that the current figures are accurate enough","believe that creatures on the seafloor do not swallow microplastics","argue that plastic waste cannot be reduced"],"a":0,"ex":"בסוף הפסקה: «Both groups agree» שצריך שיטות אחידות (standardized) כדי להשוות בין מעבדות. הם לא מסכימים שהנתונים מדויקים מספיק: קבוצה אחת אומרת במפורש שאין עדיין נתונים אמינים.","w":[["standardized","אחיד, תקני"],["caution","להזהיר"],["notwithstanding","על אף, למרות"]]}]},{"type":"rs","qs":[{"q":"Although the new irrigation method reduced water use on most of the farms that adopted it, researchers caution that it has not yet been tested in regions where rainfall is extremely scarce.","o":["Because the new irrigation method has been tested in very dry regions, researchers believe that it will reduce water use on all farms.","The new irrigation method cut water use on most farms using it; nevertheless, researchers warn that it has yet to be tried in areas with very little rain.","Researchers warn that the new irrigation method reduced water use on only a few farms, since it was mainly used in regions with very little rainfall.","Although researchers have tested the new irrigation method in extremely dry regions, it failed to reduce water use on most of the farms that adopted it."],"a":1,"ex":"התשובה הנכונה שומרת על שני החלקים: חיסכון ברוב החוות (most = the majority), ואזהרה שהשיטה עוד לא נבדקה באזורים יבשים (not yet = has yet to). התשובה השלישית משנה «most» ל-«only a few» ומוסיפה סיבה שלא הייתה במקור.","w":[["not yet","עוד לא"],["caution","להזהיר"],["scarce","נדיר, מועט"]]},{"q":"Children who eat breakfast regularly tend to perform better at school, but this does not necessarily mean that eating breakfast is what causes their higher grades, as other factors may be involved.","o":["Since eating breakfast improves children's grades, schools should make sure that every student eats breakfast regularly.","Children who eat breakfast regularly do not perform better at school than other children, because other factors determine their grades.","Other factors, rather than breakfast, are what cause some children both to eat breakfast regularly and to get higher grades at school.","A link exists between regularly eating breakfast and doing well at school; however, it is possible that something other than breakfast accounts for the better results."],"a":3,"ex":"המשפט אומר שיש קשר (מתאם) בין ארוחת בוקר לציונים, אבל לא בהכרח שהיא הסיבה. התשובה הנכונה אומרת בדיוק את זה (it is possible). התשובה השלישית מלכודת: היא קובעת בוודאות שגורמים אחרים הם הסיבה, בעוד שבמקור כתוב רק «may».","w":[["tend to","נוטה ל..."],["necessarily","בהכרח"],["account for","להסביר, להיות הגורם ל..."]]},{"q":"The museum's ancient manuscripts are extremely fragile and deteriorate quickly when exposed to light; hence, only a small number of them are displayed to the public at any given time.","o":["Because only a few of the museum's ancient manuscripts are displayed at once, they deteriorate quickly when exposed to light.","Although the museum's ancient manuscripts are very fragile, most of them are displayed to the public, since light hardly affects them.","Since light causes the museum's very delicate ancient manuscripts to decay rapidly, just a few of them are shown to visitors at once.","The museum displays all of its ancient manuscripts to the public, even though light causes a small number of them to deteriorate."],"a":2,"ex":"«hence» = ולכן: הסיבה היא שהאור הורס את כתבי היד, והתוצאה היא שמציגים מעט מהם. התשובה הנכונה שומרת על הכיוון הזה עם «Since». התשובה הראשונה הופכת סיבה ותוצאה.","w":[["hence","מכאן, ולכן"],["deteriorate","להידרדר, להתבלות"],["fragile","שביר, עדין"]]}]},{"type":"rs","qs":[{"q":"The new tax is likely to reduce pollution only insofar as companies find it cheaper to adopt cleaner technologies than to keep paying the tax on their emissions.","o":["The new tax will probably lower pollution only to the extent that switching to cleaner technologies costs companies less than continuing to pay the tax on their emissions.","The new tax will certainly reduce pollution, because companies will always prefer cleaner technologies to paying any tax.","Companies will adopt cleaner technologies only if the new tax fails to reduce pollution from their emissions.","Since cleaner technologies are cheaper than the new tax, companies have already stopped paying the tax on their emissions."],"a":0,"ex":"«insofar as» = במידה ש..., ככל ש... = «to the extent that». המס יוריד זיהום רק בתנאי שטכנולוגיה נקייה זולה יותר מהמס. התשובה השנייה הופכת «likely» (סביר) ל-«certainly» (בוודאות) ומבטלת את התנאי.","w":[["insofar as","במידה ש..., ככל ש..."],["emissions","פליטות"],["adopt","לאמץ"]]},{"q":"The treaty, albeit signed by nearly every country in the region, has had little effect so far, since few of the signatories have passed the laws needed to enforce it.","o":["Because almost every country in the region signed the treaty, it has already had a considerable effect, although a few countries have not yet passed laws to enforce it.","Few countries in the region agreed to sign the treaty, and as a result it has had hardly any effect so far, even though the laws needed to enforce it were passed.","Although almost all the region's countries signed the treaty, it has achieved very little so far, as only a small number of them have enacted the laws required to enforce it.","The treaty has had little effect so far, since nearly every country in the region refused to sign it until the necessary laws were passed."],"a":2,"ex":"«albeit» = אם כי, «little» ו-«few» = מעט, כמעט אין. כמעט כולן חתמו, ובכל זאת להסכם כמעט אין השפעה כי רק מעט מדינות חוקקו חוקים. התשובה הראשונה מלכודת: «a few» (כמה) רומז שרוב המדינות כבר חוקקו, והיא גם הופכת «little effect» להשפעה ניכרת.","w":[["albeit","אם כי"],["few","מעט (כמעט אין)"],["enforce","לאכוף"]]},{"q":"As opposed to earlier surveys, which relied on what people reported about their own diets, the new study used blood tests, thereby providing a more objective measure of what participants actually ate.","o":["Like earlier surveys, the new study relied on participants' own reports of their diets, and therefore its measure of what they ate was more objective.","The new study combined blood tests with what people reported about their own diets, so as to confirm the results that earlier surveys had obtained.","Earlier surveys used blood tests to measure what people actually ate, whereas the new study relied on participants' reports, which are less objective.","Unlike previous surveys, which depended on people's self-reports, the new study used blood tests and in this way measured more objectively what participants really ate."],"a":3,"ex":"«as opposed to» = «unlike» (בניגוד ל...), ו-«thereby» = «in this way» (ובכך). הסקרים הקודמים נשענו על דיווח עצמי, והמחקר החדש על בדיקות דם. התשובה השלישית מחליפה בין הסקרים הישנים למחקר החדש.","w":[["as opposed to","בניגוד ל..."],["thereby","ובכך, על ידי כך"],["objective","אובייקטיבי, לא מוטה"]]}]},{"type":"sc","qs":[{"q":"Since the instructions were ___, half of the participants understood the task one way and the other half understood it in a completely different way.","o":["concise","ambiguous","accurate","compelling"],"a":1,"ex":"«ambiguous» = דו-משמעי. הוראות שאפשר להבין בשתי דרכים גרמו לכל קבוצה להבין אחרת. «accurate» (מדויק) היה מוביל להבנה אחידה, ההפך ממה שקרה.","w":[["ambiguous","דו-משמעי"],["concise","תמציתי"]]},{"q":"The professor's explanation was so ___ that even students with no background in the field could follow it with ease.","o":["lucid","obscure","redundant","hostile"],"a":0,"ex":"«lucid» = ברור, צלול. גם תלמידים בלי רקע הבינו בקלות, ולכן ההסבר היה ברור מאוד. «obscure» (מעורפל, לא ברור) הוא ההפך.","w":[["lucid","ברור, צלול"],["obscure","מעורפל, לא ברור"],["background","רקע"]]},{"q":"During a storm, the flash of lightning always ___ the sound of thunder, because light travels much faster than sound.","o":["follows","imitates","outlasts","precedes"],"a":3,"ex":"«precede» = לבוא לפני. האור מהיר מהקול, ולכן רואים את הברק לפני ששומעים את הרעם. «follows» (בא אחרי) הופך את הסדר ומתנגש עם הסיבה שבסוף המשפט.","w":[["precede","לבוא לפני, להקדים"],["outlast","להחזיק מעמד יותר מ..."]]},{"q":"The plan will succeed ___ the residents are willing to cooperate; without their support, it is likely to fail.","o":["although","unless","insofar as","whereas"],"a":2,"ex":"«insofar as» = במידה ש..., ככל ש... ההצלחה תלויה בשיתוף הפעולה של התושבים, וזה מה שהחלק השני אומר (בלי תמיכה זה ייכשל). «unless» (אלא אם כן) הופך את התנאי: התוכנית תצליח רק אם התושבים לא ישתפו פעולה.","w":[["insofar as","במידה ש..., ככל ש..."],["unless","אלא אם כן"],["cooperate","לשתף פעולה"]]}]}]},{"id":"s5","title":"סימולציה 5 · רמת פטור","level":3,"hi":150,"chapters":[{"type":"sc","qs":[{"q":"The evidence linking the drug to the side effect remains ___ at best: a handful of small studies, none of which took the patients' age into account.","o":["compelling","abundant","tenuous","conclusive"],"a":2,"ex":"«Tenuous» = קלוש, חלש. אחרי הנקודתיים מתוארות ראיות דלות (כמה מחקרים קטנים ולא מבוקרים), ולכן הראיות חלשות. «compelling» ו-«conclusive» אומרות ההפך: ראיות משכנעות וחד-משמעיות.","w":[["tenuous","קלוש, רופף"],["at best","במקרה הטוב"],["conclusive","חד-משמעי, מכריע"]]},{"q":"Researchers stored a second copy of the data on a separate server ___ the original be lost in a power failure.","o":["lest","unless","provided that","so that"],"a":0,"ex":"«Lest» = כדי שלא, פן. שמרו עותק נוסף כדי שהמקור לא יאבד. «so that» היה אומר שהמטרה היא שהמקור יאבד, וזה לא הגיוני.","w":[["lest","פן, שמא, כדי שלא"],["so that","כדי ש..."]]},{"q":"Far from being ___, the senator's position on the issue has shifted at least three times in the past year.","o":["erratic","fickle","controversial","steadfast"],"a":3,"ex":"«Far from being» = רחוק מלהיות. העמדה השתנתה שלוש פעמים, כלומר היא רחוקה מלהיות יציבה: «steadfast» = יציב, נחוש. «erratic» ו-«fickle» (הפכפך) מתארות בדיוק את מה שקרה, ולכן לא מתאימות אחרי «far from».","w":[["steadfast","יציב, איתן, נחוש"],["fickle","הפכפך"],["erratic","לא יציב, הפכפך"]]},{"q":"The committee's report was ___ a full endorsement of the plan; it praised the plan's goals but rejected nearly every one of its proposed methods.","o":["undoubtedly","by no means","above all","in particular"],"a":1,"ex":"«By no means» = בשום אופן לא. הדוח דחה כמעט את כל השיטות, ולכן הוא בשום אופן לא תמיכה מלאה. «undoubtedly» היה אומר שזו ללא ספק תמיכה מלאה, וזה סותר את החלק השני.","w":[["by no means","בשום אופן לא"],["endorsement","תמיכה, אישור"]]}]},{"type":"sc","qs":[{"q":"Although the virus was first detected in a single village, it managed to ___ across the region within weeks, overwhelming local clinics.","o":["proliferate","dwindle","subside","stagnate"],"a":0,"ex":"«Proliferate» = להתרבות, להתפשט במהירות. המרפאות הוצפו, כלומר הנגיף התפשט. «dwindle» ו-«subside» פירושן להצטמצם ולשכוך, ההפך ממה שמתואר.","w":[["proliferate","להתרבות, להתפשט במהירות"],["dwindle","להצטמצם, לפחות"],["subside","לשכוך, לרדת"]]},{"q":"The study's findings are relevant to our school ___ they were based on students of the same age and background as ours.","o":["lest","whereas","inasmuch as","albeit"],"a":2,"ex":"«Inasmuch as» = מאחר ש..., במידה ש.... החלק השני הוא הסיבה לכך שהממצאים רלוונטיים. «whereas» מציין ניגוד, ואין כאן ניגוד בין שני החלקים.","w":[["inasmuch as","מאחר ש..., במידה ש..."],["whereas","בעוד ש..., ואילו"]]},{"q":"Auditors found a striking ___ between the figures the company reported to investors and those it submitted to the tax authorities: the first showed a large profit, the second a loss.","o":["resemblance","consensus","correlation","discrepancy"],"a":3,"ex":"«Discrepancy» = פער, אי-התאמה. סט אחד הראה רווח והשני הפסד, כלומר המספרים לא מתאימים זה לזה. «resemblance» (דמיון) אומרת ההפך.","w":[["discrepancy","פער, אי-התאמה"],["resemblance","דמיון"]]},{"q":"The plan had several obvious flaws; the board, ___, approved it unanimously, hoping to fix the details at a later stage.","o":["accordingly","nonetheless","likewise","namely"],"a":1,"ex":"«Nonetheless» = למרות זאת. לתוכנית היו פגמים ברורים, ובכל זאת הדירקטוריון אישר אותה. «accordingly» (בהתאם לכך) היה אומר שהאישור נבע מהפגמים, וזה לא הגיוני.","w":[["nonetheless","בכל זאת, למרות זאת"],["accordingly","בהתאם לכך, לכן"],["flaw","פגם"]]}]},{"type":"rc","title":"The Long Road from Invention to Adoption","text":["It is tempting to assume that a superior technology wins as soon as it appears. History suggests otherwise. The gap between an invention and its widespread use is often measured not in months but in decades, and economists have long tried to explain why tools that seem obviously beneficial in hindsight were, at the time, adopted with remarkable reluctance.","One reason is that a new technology rarely arrives in finished form. Early versions tend to be expensive, unreliable and difficult to repair, and their advantages over existing methods may be modest at first. A farmer who already owns horses and knows how to care for them has little reason to buy an early tractor that breaks down frequently and requires fuel he cannot easily obtain. Only after years of gradual improvement, much of it carried out by people other than the original inventor, does the new tool become clearly worth its price.","A second obstacle lies in what economists call complementary investments. A technology is seldom useful on its own; it depends on other things being in place. Electric motors, for example, offered factories little benefit as long as buildings were designed around a single steam engine that drove every machine through long belts and shafts. The real gains appeared only when owners redesigned entire factories, a costly process that many postponed until their old buildings wore out. In such cases, the delay reflects not ignorance but a reasonable calculation.","Finally, adoption is a social process. People learn about new methods mainly from neighbors, colleagues and competitors, and they tend to trust what they can observe directly. When the benefits of an innovation are hard to see, or appear only after many years, even well-informed individuals may hesitate. Institutions can slow matters further: regulations written for an older technology, or workers whose skills would lose their value, may resist a change that threatens established interests.","None of this means that slow adoption is simply wasteful. Waiting allows a technology to mature and its problems to surface before large sums are committed. Nonetheless, understanding the sources of delay can help governments and firms decide when intervention, such as training programs or shared infrastructure, might shorten a wait that serves no one."],"qs":[{"q":"The passage mainly discusses","o":["why inventors often fail to profit from their own inventions","the reasons that beneficial technologies may take a long time to be widely used","how electricity transformed the design of factories","the ways in which governments can speed up the adoption of new technologies"],"a":1,"ex":"כל הקטע מסביר למה טכנולוגיות מועילות מתפשטות לאט: מוצר לא מוגמר, השקעות משלימות ותהליך חברתי. המנועים החשמליים הם רק דוגמה בפסקה 3, והממשלות מוזכרות רק בסוף.","w":[["adoption","אימוץ"],["widespread","נפוץ, רחב היקף"]]},{"q":"According to the second paragraph, the farmer in the example would probably not buy an early tractor because","o":["he did not trust the people who sold it","the government had restricted its use","it could not do the work of a horse","it often broke down and its fuel was hard to get"],"a":3,"ex":"בפסקה 2 כתוב שהטרקטור המוקדם «breaks down frequently» ודורש דלק שקשה להשיג. אמון במוכרים ותקנות של הממשלה לא מוזכרים בפסקה הזו.","w":[["unreliable","לא אמין"],["obtain","להשיג"]]},{"q":"In the fourth paragraph, the word 'established' could best be replaced by","o":["proven","founded","existing","confirmed"],"a":2,"ex":"«Established interests» = האינטרסים הקיימים והמבוססים, של מי שנהנה מהמצב הנוכחי. לכן «existing». «proven» (מוכח) מפתה, אבל לא מדובר באינטרסים שהוכחו אלא באינטרסים שכבר קיימים.","w":[["established","מבוסס, קיים, מושרש"],["threaten","לאיים על"]]},{"q":"The example of electric motors in the third paragraph is used to show that","o":["the benefit of a new technology may depend on other costly changes being made","factory owners were generally unaware of new technologies","steam engines were more efficient than electric motors","electric motors were adopted more quickly than tractors"],"a":0,"ex":"הפסקה עוסקת ב«complementary investments»: המנוע החשמלי הועיל רק אחרי שתכננו מחדש את כל המפעל, תהליך יקר. הקטע אומר במפורש שהעיכוב «not ignorance», ולכן התשובה על חוסר מודעות שגויה.","w":[["complementary","משלים"],["postpone","לדחות"]]},{"q":"It can be inferred from the last paragraph that the author believes that","o":["some delays in adoption serve a useful purpose, while others might reasonably be shortened","governments should avoid any involvement in the spread of new technologies","every delay in adopting a useful technology is a waste of resources","most new technologies are adopted too quickly to be properly tested"],"a":0,"ex":"הכותב אומר שהמתנה מאפשרת לטכנולוגיה להבשיל (כלומר יש בה תועלת), ובכל זאת אפשר לקצר המתנה «that serves no one». «every delay is a waste» סותרת את המשפט «None of this means that slow adoption is simply wasteful».","w":[["nonetheless","בכל זאת, למרות זאת"],["mature","להבשיל"],["intervention","התערבות"]]}]},{"type":"rs","qs":[{"q":"Granted that the new vaccine is more expensive than the old one, its far greater effectiveness makes it the better choice for the national health service.","o":["Because the new vaccine is more expensive than the old one, the national health service should prefer the old one, despite its lower effectiveness.","Although the new vaccine costs more than the old one, the national health service would do better to choose it, since it is considerably more effective.","The new vaccine is both cheaper and more effective than the old one, so the national health service should choose it.","Although the new vaccine is more effective than the old one, its higher price makes it the less sensible choice for the national health service."],"a":1,"ex":"«Granted that» = נכון ש..., גם אם נודה ש.... המשפט מודה שהחיסון החדש יקר יותר, ובכל זאת קובע שהוא עדיף כי הוא יעיל בהרבה. התשובה הנכונה שומרת על שני החלקים עם «Although» ו-«since». התשובה האחרונה הופכת את המסקנה (המחיר מכריע).","w":[["granted that","נכון ש..., גם אם נודה ש..."],["although","למרות ש..."],["effectiveness","יעילות"]]},{"q":"The town's economic decline was caused not so much by the closure of the mine as by the failure of local leaders to develop any alternative source of employment in the years that followed.","o":["The closure of the mine was the main reason for the town's economic decline, although local leaders also failed to create new jobs afterwards.","The closure of the mine and the local leaders' failure to create new jobs contributed equally to the town's economic decline.","Local leaders failed to develop new sources of employment because the closure of the mine had already ruined the town's economy.","It was chiefly the local leaders' failure to create other jobs after the mine closed, rather than the closure itself, that brought about the town's economic decline."],"a":3,"ex":"«Not so much X as Y» = לא כל כך X אלא בעיקר Y. הסיבה העיקרית היא כישלון המנהיגים, לא סגירת המכרה. התשובה הראשונה הופכת את הדגש, והשנייה אומרת שהשתיים תרמו באותה מידה.","w":[["not so much X as Y","לא כל כך X אלא Y"],["chiefly","בעיקר"],["rather than","במקום, ולא"]]},{"q":"Officials delayed announcing the results of the inquiry, lest premature disclosure should provoke public panic before the full extent of the water contamination had been established.","o":["Officials held back the results of the inquiry for fear that releasing them too early might cause public panic, since the extent of the water contamination was not yet fully known.","Because the public had already panicked, officials decided to delay announcing the results of the inquiry into the water contamination.","Officials released the results of the inquiry early in order to prevent public panic over the extent of the water contamination.","Officials delayed announcing the results of the inquiry until they had confirmed that the water contamination was too limited to cause public panic."],"a":0,"ex":"«Lest» = מחשש ש..., כדי שלא. הפקידים עיכבו את הפרסום כדי שלא תפרוץ בהלה לפני שהיקף הזיהום ידוע. בתשובה השנייה הבהלה כבר קרתה, והאחרונה מוסיפה טענה שלא נאמרה (שהזיהום מוגבל).","w":[["lest","פן, שמא, כדי שלא"],["premature","מוקדם מדי"],["extent","היקף"]]}]},{"type":"rs","qs":[{"q":"Hardly had the company launched its new smartphone when reports of overheating batteries began to appear, forcing it to recall nearly a quarter of a million devices within a month.","o":["The company recalled nearly a quarter of a million of its new smartphones before any reports of overheating batteries had appeared.","Several years after the company launched its new smartphone, reports of overheating batteries forced it to recall nearly a quarter of a million devices.","Almost as soon as the company's new smartphone went on sale, reports of overheating batteries emerged, and within a month the company had to recall almost 250,000 devices.","Almost as soon as the company's new smartphone went on sale, reports of overheating batteries emerged, but the company refused to recall any of the devices."],"a":2,"ex":"«Hardly had... when» = אך ורק... וכבר, מיד אחרי ש.... הדיווחים הופיעו מיד אחרי ההשקה והובילו לריקול. התשובה השנייה משנה את הזמן (כמה שנים אחרי), והאחרונה הופכת את התוצאה (סירבה לריקול).","w":[["hardly","כמעט לא"],["recall","להחזיר מוצר מהשוק, ריקול"],["as soon as","ברגע ש..., מיד כש..."]]},{"q":"Inasmuch as the survey relied solely on volunteers, who tend to be more health-conscious than the general population, its conclusions about national eating habits should be treated with considerable caution.","o":["The survey's conclusions about national eating habits are reliable, since its volunteers were more health-conscious than the general population.","Since the survey was based only on volunteers, who are generally more health-conscious than most people, its findings about the nation's eating habits may not be fully trustworthy.","Since the survey was based only on volunteers, who are generally less health-conscious than most people, its findings about the nation's eating habits may not be fully trustworthy.","Since the survey's findings about the nation's eating habits may not be trustworthy, researchers decided to rely only on volunteers."],"a":1,"ex":"«Inasmuch as» = מאחר ש.... מכיוון שהסקר נשען רק על מתנדבים שמקפידים יותר על בריאות, צריך להיזהר במסקנות. התשובה השלישית הופכת את ההשוואה (פחות מקפידים), והרביעית הופכת סיבה ותוצאה.","w":[["inasmuch as","מאחר ש..., במידה ש..."],["solely","אך ורק, בלעדית"],["caution","זהירות"]]},{"q":"The treaty was by no means the first attempt to limit the arms race; it was, nonetheless, the first to include a system for verifying that both sides were actually keeping their commitments.","o":["The treaty was the first attempt ever made to limit the arms race, and it included a system for checking that both sides kept their commitments.","Several earlier agreements had tried to limit the arms race, and, like the treaty, they included a system for checking that both sides kept their commitments.","Other agreements had tried to limit the arms race before this treaty, but it was the first one that provided a means of checking whether both sides honored their commitments.","Since earlier agreements had failed to limit the arms race, the treaty abandoned the idea of checking whether both sides kept their commitments."],"a":2,"ex":"«By no means the first» = בשום אופן לא הראשון, כלומר היו ניסיונות קודמים. «nonetheless» = ובכל זאת, הוא הראשון עם מנגנון פיקוח. התשובה הראשונה אומרת שזה הניסיון הראשון, והשנייה אומרת שגם להסכמים הקודמים היה פיקוח.","w":[["by no means","בשום אופן לא"],["nonetheless","בכל זאת, למרות זאת"],["verify","לאמת, לוודא"]]}]},{"type":"sc","qs":[{"q":"The government introduced strict measures to ___ water use during the drought, including fines for watering gardens during the day.","o":["boost","subsidize","curtail","justify"],"a":2,"ex":"«Curtail» = לצמצם, לקצץ. קנסות על השקיה בשעות היום נועדו להפחית צריכת מים בזמן בצורת. «boost» ו-«subsidize» היו מעודדות צריכה, ההפך מהמטרה.","w":[["curtail","לצמצם, לקצץ"],["drought","בצורת"],["subsidize","לסבסד"]]},{"q":"The new rules had ___ taken effect when several companies announced they would challenge them in court, so swift was the opposition.","o":["eventually","gradually","long since","hardly"],"a":3,"ex":"«Hardly... when» = רק... וכבר, מיד אחרי ש.... סוף המשפט אומר שההתנגדות הייתה מהירה מאוד, ולכן החברות הודיעו כמעט מיד. «long since» (מזמן) סותרת את המהירות.","w":[["hardly","כמעט לא"],["swift","מהיר"],["take effect","להיכנס לתוקף"]]},{"q":"The scale of the flooding was ___: in more than two centuries of record-keeping, the river had never risen so high.","o":["unprecedented","predictable","negligible","routine"],"a":0,"ex":"«Unprecedented» = חסר תקדים. הנהר מעולם לא עלה כל כך גבוה ב-200 שנות תיעוד, כלומר לא היה כדבר הזה. «routine» ו-«predictable» אומרות שזה רגיל וצפוי, ההפך.","w":[["unprecedented","חסר תקדים"],["negligible","זניח"]]},{"q":"For decades, a reliable treatment for the disease remained ___: each drug that looked promising in early tests failed in later trials.","o":["accessible","elusive","affordable","obsolete"],"a":1,"ex":"«Elusive» = חמקמק, קשה להשגה. כל תרופה נכשלה, כך שטיפול אמין לא נמצא. «accessible» (נגיש) אומרת ההפך, ו-«affordable» עוסקת במחיר, שלא מוזכר כאן.","w":[["elusive","חמקמק, קשה להשגה"],["obsolete","מיושן, שאבד עליו הכלח"]]}]}]}];
